mapper.update:
update user
username = #{username}, password = #{password}, name = #{name}, role = #{role}, account = #{account}, phone = #{phone}, avatar = #{avatar}, points = #{points}, total_recycle_count = #{totalRecycleCount}, total_recycle_weight = #{totalRecycleWeight}, carbon_saved = #{carbonSaved}, status = #{status},
where id = #{id}

mapper.select:
select * from `user`

    and username like concat('%', #{username}, '%')
    and name like concat('%', #{name}, '%')
    and phone = #{phone}
    and status = #{status}

order by create_time desc
